//! `fineprint-ingest vocab --cr <rules.txt> [--out <file>|-] [--check]`.
//!
//! - Default `--out` is [`DEFAULT_OUT`], resolved against the current directory (run from the
//!   repository root, as every documented command is).
//! - Without `--check`: writes the generated bytes to `--out` (or stdout for `-`) and prints one
//!   summary line (on stderr when the JSON goes to stdout). A file is written atomically: the
//!   bytes go to a new temporary file next to the destination, which then replaces it, so a
//!   failed write never leaves a partial file.
//! - `--cr` and `--out` take the next argument as their path; an argument that is exactly one
//!   of the CLI's own options (`--cr`, `--out`, `--check`) is a usage error there (write
//!   `./--check` for a file of that name).
//! - With `--check`: writes nothing, compares the generated bytes with the `--out` file and
//!   prints one summary line. A missing or different file is a violation; the message names the
//!   first differing top-level member and never quotes CR text or values from the file.
//!
//! Exit codes (the xtask convention): 0 success, 1 violation (check mismatch or keyword id
//! collision), 2 usage or input error.

use std::ffi::OsString;
use std::io::Write;
use std::path::{Path, PathBuf};

use fineprint_dsl::vocab::{RulesVocabulary, VocabError};
use serde_json::Value;

use super::{GenError, generate};

/// The committed vocabulary, relative to the repository root.
pub const DEFAULT_OUT: &str = "crates/fineprint-dsl/data/vocab.json";

/// The usage text.
pub const USAGE: &str = "usage: fineprint-ingest vocab --cr <rules.txt> [--out <file>|-] [--check]";

/// The CLI's own options; none of them is accepted as a path value.
const OPTIONS: [&str; 3] = ["--cr", "--out", "--check"];

/// The value of the path option `opt`: the next argument, unless it is missing or is exactly
/// one of [`OPTIONS`].
fn path_value<'a>(
    opt: &str,
    it: &mut impl Iterator<Item = &'a OsString>,
) -> Result<&'a OsString, String> {
    match it.next() {
        None => Err(format!("{opt} needs a path")),
        Some(v) if OPTIONS.iter().any(|o| v == o) => Err(format!(
            "{opt} needs a path but is followed by the option {}",
            v.to_string_lossy()
        )),
        Some(v) => Ok(v),
    }
}

struct Args {
    cr: PathBuf,
    out: OsString,
    check: bool,
}

fn parse_args(args: &[OsString]) -> Result<Args, String> {
    let mut cr = None;
    let mut out = None;
    let mut check = false;
    let mut it = args.iter();
    while let Some(a) = it.next() {
        match a.to_str() {
            Some("--cr") => {
                let v = path_value("--cr", &mut it)?;
                if cr.replace(PathBuf::from(v)).is_some() {
                    return Err("--cr given twice".to_owned());
                }
            }
            Some("--out") => {
                let v = path_value("--out", &mut it)?;
                if out.replace(v.clone()).is_some() {
                    return Err("--out given twice".to_owned());
                }
            }
            Some("--check") => check = true,
            _ => return Err(format!("unexpected argument {}", a.to_string_lossy())),
        }
    }
    let cr = cr.ok_or("--cr <rules.txt> is required")?;
    let out = out.unwrap_or_else(|| OsString::from(DEFAULT_OUT));
    if check && out == "-" {
        return Err("--check compares with a file; --out - is not allowed".to_owned());
    }
    Ok(Args { cr, out, check })
}

/// Runs the `vocab` subcommand; returns the exit code.
pub fn run(args: &[OsString], stdout: &mut dyn Write, stderr: &mut dyn Write) -> i32 {
    let args = match parse_args(args) {
        Ok(a) => a,
        Err(m) => {
            let _ = writeln!(stderr, "vocab: {m}\n{USAGE}");
            return 2;
        }
    };
    let cr = match std::fs::read(&args.cr) {
        Ok(b) => b,
        Err(e) => {
            let _ = writeln!(stderr, "vocab: cannot read --cr {}: {e}", args.cr.display());
            return 2;
        }
    };
    let vocab = match generate(&cr) {
        Ok(v) => v,
        Err(e) => return fail(stderr, &e),
    };
    let bytes = match vocab.to_canonical_bytes() {
        Ok(b) => b,
        Err(e) => {
            let _ = writeln!(stderr, "vocab: {e}");
            return 2;
        }
    };
    let summary = summary(&vocab);
    let out_path = PathBuf::from(&args.out);
    if args.check {
        return check(&args, &bytes, &vocab, &summary, stdout, stderr);
    }
    if args.out == "-" {
        if stdout.write_all(&bytes).is_err() {
            return 2;
        }
        let _ = writeln!(stderr, "vocab: wrote stdout ({summary})");
        return 0;
    }
    if let Err(e) = write_atomic(&out_path, &bytes) {
        let _ = writeln!(
            stderr,
            "vocab: cannot write --out {}: {e}",
            out_path.display()
        );
        return 2;
    }
    let _ = writeln!(stdout, "vocab: wrote {} ({summary})", out_path.display());
    0
}

/// The temporary file [`write_atomic`] uses for `dest`: `.<file name>.<pid>.tmp` in the same
/// directory (so the final rename never crosses a file system).
///
/// # Errors
/// An `InvalidInput` error when `dest` has no file name.
pub fn temp_path_for(dest: &Path) -> std::io::Result<PathBuf> {
    let name = dest.file_name().ok_or_else(|| {
        std::io::Error::new(
            std::io::ErrorKind::InvalidInput,
            "the --out path has no file name",
        )
    })?;
    let mut tmp = OsString::from(".");
    tmp.push(name);
    tmp.push(format!(".{}.tmp", std::process::id()));
    Ok(match dest.parent() {
        Some(p) if !p.as_os_str().is_empty() => p.join(tmp),
        _ => PathBuf::from(tmp),
    })
}

/// Writes `bytes` to `dest` atomically: a new temporary file ([`temp_path_for`], created with
/// `create_new`, so an existing path is never followed or overwritten) is written, flushed and
/// synced, then renamed over `dest` (`std::fs::rename` replaces an existing file on Windows,
/// macOS and Linux). On failure the temporary file is removed (best effort) if this call
/// created it, `dest` is left as it was, and the original error is returned.
///
/// # Errors
/// The first I/O error.
pub fn write_atomic(dest: &Path, bytes: &[u8]) -> std::io::Result<()> {
    let tmp = temp_path_for(dest)?;
    let mut file = std::fs::OpenOptions::new()
        .write(true)
        .create_new(true)
        .open(&tmp)?;
    let result = file
        .write_all(bytes)
        .and_then(|()| file.flush())
        .and_then(|()| file.sync_all());
    drop(file);
    let result = result.and_then(|()| std::fs::rename(&tmp, dest));
    if result.is_err() {
        let _ = std::fs::remove_file(&tmp);
    }
    result
}

fn fail(stderr: &mut dyn Write, e: &GenError) -> i32 {
    let _ = writeln!(stderr, "vocab: {e}");
    e.exit_code()
}

fn summary(v: &RulesVocabulary) -> String {
    format!(
        "{} card types, {} supertypes, {} subtype groups, {} keyword abilities, \
         {} keyword actions, {} counter kinds, {} predefined tokens",
        v.card_types.len(),
        v.supertypes.len(),
        v.subtype_groups.len(),
        v.keyword_abilities.len(),
        v.keyword_actions.len(),
        v.counter_kinds.len(),
        v.predefined_tokens.len()
    )
}

fn check(
    args: &Args,
    bytes: &[u8],
    vocab: &RulesVocabulary,
    summary: &str,
    stdout: &mut dyn Write,
    stderr: &mut dyn Write,
) -> i32 {
    let path = Path::new(&args.out);
    let committed = match std::fs::read(path) {
        Ok(b) => b,
        Err(e) if args.out == DEFAULT_OUT => {
            // The crate embeds this file (`include_bytes!`), so it cannot be rebuilt by
            // running the generator: it has to come back from git.
            let _ = writeln!(
                stderr,
                "vocab: {} is missing or unreadable ({e}); it is the bundled vocabulary \
                 fineprint-dsl embeds, so nothing builds without it: restore it from git with \
                 `git checkout -- {DEFAULT_OUT}`",
                path.display()
            );
            return 1;
        }
        Err(e) => {
            let _ = writeln!(
                stderr,
                "vocab: {} is missing or unreadable ({e}); regenerate it",
                path.display()
            );
            return 1;
        }
    };
    if committed == bytes {
        let _ = writeln!(
            stdout,
            "vocab: {} matches the CR ({summary})",
            path.display()
        );
        return 0;
    }
    let _ = writeln!(
        stderr,
        "vocab: {} differs from regeneration: {}; to regenerate it, rerun the same command \
         without --check (keeping --cr {} --out {})",
        path.display(),
        first_difference(&committed, vocab),
        args.cr.display(),
        path.display()
    );
    1
}

/// A fixed description of why a file does not load, naming at most a field (R12: never the
/// offending value, never the underlying error's text).
fn load_failure(e: &VocabError) -> String {
    match e {
        VocabError::Json(_) => {
            "the file is not a valid RulesVocabulary (unparseable JSON)".to_owned()
        }
        VocabError::Version(_) => {
            "the file is not a valid RulesVocabulary (field: vocabularyVersion)".to_owned()
        }
        VocabError::Shape(_) => {
            "the file is not a valid RulesVocabulary (wrong shape: unknown, missing or \
             mistyped member)"
                .to_owned()
        }
        VocabError::Invalid { path, .. } => {
            format!("the file is not a valid RulesVocabulary (field: {path})")
        }
    }
}

/// Names the first top-level member that differs (wire order), or why the file cannot be
/// compared member by member. Never contains CR text.
#[must_use]
pub fn first_difference(committed: &[u8], vocab: &RulesVocabulary) -> String {
    let loaded = match RulesVocabulary::from_slice(committed) {
        Ok(v) => v,
        Err(e) => return format!("the committed file does not load: {}", load_failure(&e)),
    };
    let (Ok(Value::Object(a)), Ok(Value::Object(b))) =
        (serde_json::to_value(&loaded), serde_json::to_value(vocab))
    else {
        return "the vocabularies cannot be compared".to_owned();
    };
    const ORDER: [&str; 9] = [
        "vocabularyVersion",
        "crEffectiveDate",
        "cardTypes",
        "supertypes",
        "subtypeGroups",
        "keywordAbilities",
        "keywordActions",
        "counterKinds",
        "predefinedTokens",
    ];
    for key in ORDER {
        if a.get(key) != b.get(key) {
            return format!("first differing section `{key}`");
        }
    }
    "the content is equal but the bytes are not canonical".to_owned()
}
